use chronix::Chronix;
use chronix::arrow::util::pretty::print_batches;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let db = Chronix::open_small("./data")?;

    let batches = db.sql({{query_rust}})?;
    print_batches(&batches)?;
    Ok(())
}

