import asyncio{{py_os}}

from chronix_client import ChronixClient


async def main() -> None:
    async with ChronixClient({{base_url_py}}{{auth_py}}) as client:
        # {{range}}
        result = await client.prom_query_range(
            {{query_py}},
            start="{{start}}",
            end="{{end}}",
            step="{{step}}",
        )
        for series in result["data"]["result"]:
            print(series["metric"], len(series["values"]), "points")


asyncio.run(main())
